ify-end"><button type="button" @click="close" class="min-h-11 rounded-lg px-4 text-sm font-semibold text-muted hover:bg-canvas">Cancel</button><button :disabled="submitting" class="min-h-11 rounded-lg bg-brand px-5 text-sm font-semibold text-white shadow-sm hover:bg-brand-hover disabled:cursor-wait disabled:bg-blue-300"><span x-text="submitting ? 'Saving…' : '{{ $item->review ? 'Save changes' : 'Publish review' }}'"></span></button></div></form>@if($item->review)<form method="POST" action="{{ route('reviews.destroy',$item->review) }}" class="mt-3 border-t border-line pt-4">@csrf @method('DELETE')<button class="inline-flex min-h-11 items-center text-sm font-semibold text-danger hover:text-danger">Delete review</button></form>@endif</div></div></div>@endif</div><p class="shrink-0 text-right text-sm font-semibold tabular-nums text-ink sm:text-base">₱{{ number_format($item->line_total,2) }}</p></div>@endforeach</div></section>@endforeach